/**
 * api/client.js
 * Cấu hình Axios và tất cả các hàm gọi API backend Django.
 *
 * Xác thực: dùng Basic Auth trong dev (username:password).
 * Thay bằng Token/JWT khi lên production.
 */
import axios from 'axios';

// Lấy credentials từ localStorage (được lưu khi đăng nhập)
function getAuthHeader() {
  const creds = localStorage.getItem('vninvest_creds');
  if (!creds) return {};
  return { Authorization: `Basic ${creds}` };
}

const apiClient = axios.create({
  baseURL: '/api',
  headers: { 'Content-Type': 'application/json' },
});

// Tự động đính kèm auth header vào mỗi request
apiClient.interceptors.request.use((config) => {
  const auth = getAuthHeader();
  config.headers = { ...config.headers, ...auth };
  return config;
});

// Nếu 401 → xoá credentials và reload
apiClient.interceptors.response.use(
  (res) => res,
  (err) => {
    if (err.response?.status === 401) {
      localStorage.removeItem('vninvest_creds');
      window.location.href = '/login';
    }
    return Promise.reject(err);
  }
);

// --- Portfolio APIs ---
export const getPortfolios = () => apiClient.get('/portfolios/');
export const createPortfolio = (data) => apiClient.post('/portfolios/', data);
export const getPortfolio = (id) => apiClient.get(`/portfolios/${id}/`);
export const updatePortfolio = (id, data) => apiClient.put(`/portfolios/${id}/`, data);
export const deletePortfolio = (id) => apiClient.delete(`/portfolios/${id}/`);

// --- Transaction APIs ---
export const getTransactions = (portfolioId) =>
  apiClient.get(`/portfolios/${portfolioId}/transactions/`);
export const createTransaction = (portfolioId, data) =>
  apiClient.post(`/portfolios/${portfolioId}/transactions/`, data);
export const updateTransaction = (id, data) =>
  apiClient.put(`/transactions/${id}/`, data);
export const deleteTransaction = (id) =>
  apiClient.delete(`/transactions/${id}/`);

// --- Analytics APIs ---
export const getHoldings = (portfolioId) =>
  apiClient.get(`/portfolios/${portfolioId}/holdings/`);
export const getSummary = (portfolioId) =>
  apiClient.get(`/portfolios/${portfolioId}/summary/`);
export const getChartData = (portfolioId, days = 90) =>
  apiClient.get(`/portfolios/${portfolioId}/chart/?days=${days}`);
export const getAllocation = (portfolioId) =>
  apiClient.get(`/portfolios/${portfolioId}/allocation/`);

// --- Sync ---
export const syncPrices = (portfolioId, days = 30) =>
  apiClient.post(`/portfolios/${portfolioId}/sync/`, { days });

// --- Watchlist ---
export const getWatchlistGroups = () => apiClient.get('/watchlist/groups/');
export const createWatchlistGroup = (data) => apiClient.post('/watchlist/groups/', data);
export const updateWatchlistGroup = (id, data) => apiClient.patch(`/watchlist/groups/${id}/`, data);
export const deleteWatchlistGroup = (id) => apiClient.delete(`/watchlist/groups/${id}/`);
export const addWatchlistItem = (groupId, symbol) =>
  apiClient.post(`/watchlist/groups/${groupId}/items/`, { symbol });
export const deleteWatchlistItem = (itemId) => apiClient.delete(`/watchlist/items/${itemId}/`);
export const seedWatchlist = () => apiClient.post('/watchlist/seed/');
export const syncWatchlistPrices = (days = 5) => apiClient.post('/watchlist/sync/', { days });

export default apiClient;
